    [int]$IntervalMs = 1000,
    [int]$IdleThresholdSec = 300,
    [string]$LogFile = "$PSScriptRoot/active-window-log.csv"
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Add-Type -Namespace Win32 -Name NativeMethods -MemberDefinition @'
using System;
using System.Runtime.InteropServices;
using System.Text;

public static class NativeMethods {
    [DllImport("user32.dll")]
    public static extern IntPtr GetForegroundWindow();

    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int count);

    [DllImport("user32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    public static extern int GetWindowTextLength(IntPtr hWnd);

    [DllImport("user32.dll")]
    public static extern bool IsWindow(IntPtr hWnd);

    [DllImport("user32.dll")]
    public static extern bool GetLastInputInfo(ref LASTINPUTINFO plii);

    [DllImport("user32.dll")]
    public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out int lpdwProcessId);
}

[StructLayout(LayoutKind.Sequential)]
public struct LASTINPUTINFO {
    public uint cbSize;
    public uint dwTime;
}
'@

function Get-IdleMilliseconds {
    $info = New-Object LASTINPUTINFO
    $info.cbSize = [System.Runtime.InteropServices.Marshal]::SizeOf([type]::GetType('LASTINPUTINFO'))
    [void][Win32.NativeMethods]::GetLastInputInfo([ref]$info)
    $tick = [Environment]::TickCount
    $delta = $tick - [int]$info.dwTime
    if ($delta -lt 0) { $delta = [int]::MaxValue + $delta } # handle wrap
    return [int64]$delta
}

function Get-ActiveWindowInfo {
    $h = [Win32.NativeMethods]::GetForegroundWindow()
    if ($h -eq [IntPtr]::Zero) { return $null }
    if (-not [Win32.NativeMethods]::IsWindow($h)) { return $null }
    $len = [Win32.NativeMethods]::GetWindowTextLength($h)
    $sb = New-Object System.Text.StringBuilder ([Math]::Max(1, $len + 1))
    [void][Win32.NativeMethods]::GetWindowText($h, $sb, $sb.Capacity)
    $title = $sb.ToString()
    [void][Win32.NativeMethods]::GetWindowThreadProcessId($h, [ref]([int]$pid = 0))
    $pname = ''
    try { $pname = (Get-Process -Id $pid -ErrorAction Stop).ProcessName } catch { $pname = '' }
    [pscustomobject]@{ Handle = $h; Title = $title; ProcessId = $pid; ProcessName = $pname }
}

$IdleThresholdMs = [int]($IdleThresholdSec * 1000)

if (-not (Test-Path -LiteralPath (Split-Path -Parent $LogFile))) {
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $LogFile) | Out-Null
}

if (-not (Test-Path -LiteralPath $LogFile)) {
    'timestamp,state,title,process_name,process_id' | Out-File -FilePath $LogFile -Encoding UTF8
}

$prevTitle = $null
$prevState = $null
$prevPid = $null

$stop = $false
$onExit = {
    $global:stop = $true
}

trap { continue }

$null = Register-EngineEvent PowerShell.Exiting -Action $onExit | Out-Null

while (-not $stop) {
    $idleMs = Get-IdleMilliseconds
    $now = Get-Date
    if ($idleMs -ge $IdleThresholdMs) {
        if ($prevState -ne 'Idle') {
            "$($now.ToString('s'))Z,Idle,,," | Out-File -FilePath $LogFile -Append -Encoding UTF8
            $prevState = 'Idle'
            $prevTitle = $null
            $prevPid = $null
        }
    }
    else {
        $info = Get-ActiveWindowInfo
        $title = $info.Title
        $pid = $info.ProcessId
        $pname = $info.ProcessName
        if ([string]::IsNullOrWhiteSpace($title)) { $title = '(No Title)' }
        $changed = ($prevState -ne 'Active') -or ($title -ne $prevTitle) -or ($pid -ne $prevPid)
        if ($changed) {
            "$($now.ToString('s'))Z,Active,`"$title`",$pname,$pid" | Out-File -FilePath $LogFile -Append -Encoding UTF8
            $prevState = 'Active'
            $prevTitle = $title
            $prevPid = $pid
        }
    }
    Start-Sleep -Milliseconds $IntervalMs
}
"}

